var originalNumber = number;
var sb = new System.Text.StringBuilder(32);

if (number / 1_000_000 > 0)
{
    sb.Append(Convert(number / 1_000_000)).Append("millió");
    number %= 1_000_000;
}

if (number / 1_000 > 0)
{
    sb.Append(Convert(number / 1_000)).Append("ezer");
    number %= 1_000;
    if (number > 0)
    {
        sb.Append('-');
    }
}

if (number / 100 > 0)
{
    sb.Append(HundredsMap[number / 100]);
    number %= 100;
}

if (number > 0)
{
    if (number < 10)
    {
        sb.Append(UnitsMap[number]);
    }
    else
    {
        sb.Append(TensMap[number / 10]);
        if (number % 10 > 0)
        {
            sb.Append(UnitsMap[number % 10]);
        }
    }
}

var result = sb.ToString().Trim();

