1. using System.Collections.Frozen;
2. 
3. namespace Textualizer.Localisation.NumberToWords;
4. 
5. /// <summary>
6. /// Converts numbers to their Swedish word representation.
7. /// Handles cardinal and ordinal forms with proper gender agreement.
8. /// </summary>
9. public class SwedishNumberToWordsConverter : INumberToWordsConverter
10. {
11.     private static readonly string[] UnitsMap =
12.         ["noll", "ett", "två", "tre", "fyra", "fem", "sex", "sju", "åtta", "nio",
13.          "tio", "elva", "tolv", "tretton", "fjorton", "femton", "sexton", "sjutton",
14.          "arton", "nitton"];
15. 
16.     private static readonly string[] TensMap =
17.         ["", "tio", "tjugo", "trettio", "fyrtio", "femtio", "sextio", "sjuttio", "åttio", "nittio"];
18. 
19.     private static readonly FrozenDictionary<long, string> OrdinalExceptions = new Dictionary<long, string>
20.     {
21.         { 1, "första" },
22.         { 2, "andra" },
23.         { 3, "tredje" },
24.         { 4, "fjärde" },
25.         { 5, "femte" },
26.         { 6, "sjätte" },
27.         { 7, "sjunde" },
28.         { 8, "åttonde" },
29.         { 9, "nionde" },
30.         { 10, "tionde" },
31.         { 11, "elfte" },
32.         { 12, "tolfte" }
33.     }.ToFrozenDictionary();
34. 
35.     /// <inheritdoc />
36.     public string Convert(long number)
37.     {
38.         if (number == 0)
39.         {
40.             return UnitsMap[0];
41.         }
42. 
